func RegisterCommentServiceBridgeServer(s *http.Server, srv CommentServiceHookedBridger) {
	r := s.Route("/")
	r.GET("/api/v1/comments", _CommentService_ListComments0_Bridge_Handler(srv))
	r.GET("/api/v1/comments/:id", _CommentService_GetComment0_Bridge_Handler(srv))
	r.POST("/api/v1/comments", _CommentService_CreateComment0_Bridge_Handler(srv))
	r.PUT("/api/v1/comments/:comment.id", _CommentService_UpdateComment0_Bridge_Handler(srv))
	r.DELETE("/api/v1/comments/:id", _CommentService_DeleteComment0_Bridge_Handler(srv))
	r.GET("/api/v1/comments/:id/replies", _CommentService_GetCommentReplies0_Bridge_Handler(srv))
	r.POST("/api/v1/comments/:id/replies", _CommentService_CreateCommentReply0_Bridge_Handler(srv))
	r.POST("/api/v1/comments/:id/likes", _CommentService_LikeComment0_Bridge_Handler(srv))
	r.POST("/api/v1/comments/:id/dislikes", _CommentService_DislikeComment0_Bridge_Handler(srv))
	r.POST("/api/v1/comments/:id/report", _CommentService_ReportComment0_Bridge_Handler(srv))
}

